-- ============================================================
-- Seed: Junior Set 18 applications (from legacy registrations dump)
-- Prerequisites:
--   1. Run migration_detailed_application.sql
--   2. Zones must exist with names matching legacy zone field:
--        Kaduna, Minna, Ufuma  (adjust zone_map below if your codes differ)
--   3. Run once; uses application_token = legacy reg_id
-- Status mapping: admitted -> students.status=admitted + applications.status=admitted
--                 NULL/other -> applicant + pending
-- set_number = 18
-- ============================================================

-- Helper: map zone name -> id (adjust if your zone names/codes differ)
-- SELECT id, name, code FROM zones;

SET @zone_kaduna := (SELECT id FROM zones WHERE name LIKE '%Kaduna%' OR code IN ('KAD','KD') LIMIT 1);
SET @zone_minna  := (SELECT id FROM zones WHERE name LIKE '%Minna%'  OR code IN ('MNA','MN') LIMIT 1);
SET @zone_ufuma  := (SELECT id FROM zones WHERE name LIKE '%Ufuma%'  OR code IN ('UFM','UF') LIMIT 1);

-- Fallback if not found
SET @zone_kaduna := IFNULL(@zone_kaduna, (SELECT id FROM zones ORDER BY id LIMIT 1));
SET @zone_minna  := IFNULL(@zone_minna,  @zone_kaduna);
SET @zone_ufuma  := IFNULL(@zone_ufuma,  @zone_kaduna);


