-- applications workflow rows for every seeded student
INSERT INTO applications (student_id, zone_id, application_year, status, acknowledgment_sms_sent, reviewed_at)
SELECT s.id, s.zone_id, YEAR(COALESCE(s.application_date, NOW())),
       CASE WHEN s.status = 'admitted' THEN 'admitted' ELSE 'pending' END,
       1,
       CASE WHEN s.status = 'admitted' THEN COALESCE(s.application_date, NOW()) ELSE NULL END
FROM students s
WHERE s.set_number = 18
  AND s.application_token IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM applications a WHERE a.student_id = s.id);

-- Optional: ensure set 18 exists
INSERT IGNORE INTO sets (set_number, status, started_year, current_sequence)
VALUES (18, 'active_junior', 2025, 1);

SELECT CONCAT('Seeded students set 18: ', COUNT(*)) AS info FROM students WHERE set_number = 18;
